CREATE TABLE run_log (run_id int, rows_read int, rows_rejected int);
INSERT INTO run_log VALUES (1,100,5),(2,120,12),(3,90,0),(4,100,9),(5,110,10);
SELECT run_id, ROUND(rows_rejected * 100.0 / rows_read, 1) AS rejection_pct
FROM run_log
WHERE rows_rejected * 100.0 / rows_read > 8
ORDER BY run_id;

