def problems(spec):
    found = []
    if not spec["title"]:
        found.append("no title")
    if not spec["ylabel"]:
        found.append("no y label")
    if len(spec["x"]) != len(spec["y"]):
        found.append("length mismatch")
    if not spec["y"]:
        found.append("empty series")
    return found

